# answers worked here once, recomputed by the verifier's own helpers
_ANS = {
    "cs-rsa-d": {(61, 53, 17): 2753, (11, 13, 7): 103, (17, 23, 3): 235, (7, 19, 5): 65},
    "cs-hash-ring": {("10 40 70", 25): 40, ("10 40 70", 85): 10, ("5 30 55 80", 55): 55, ("20 60", 61): 20},
}
for code, q in ADD:
    if q.name == "cs-rsa-d":
        for c in q.cases: c["ans"] = _ANS[q.name][(c["p"], c["q"], c["ee"])]
    if q.name == "cs-hash-ring":
        for c in q.cases: c["ans"] = _ANS[q.name][(c["nodes"], c["h"])]
    if q.name == "cs-matching":
        for c in q.cases:
            ps = [t.split("-") for t in c["pairs"].split()]
            W = sorted({w for w, _ in ps}); J = sorted({j for _, j in ps})
            c["spec"] = " ".join([f"s>w{w}:1" for w in W] + [f"w{w}>j{j}:1" for w, j in ps] + [f"j{j}>t:1" for j in J])
    if q.name == "cs-kmeans-step":
        for c in q.cases:
            P = [int(t) for t in c["pts"].split()]
            mine = [p for p in P if abs(p - c["c1"]) <= abs(p - c["c2"])]
            c["ans"] = round(sum(mine) / len(mine), 6)
    if q.name in ("cs-hof", "cs-pass-sharing", "cs-precedence-eval"):
        import contextlib, io
        for c in q.cases:
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                if q.name == "cs-precedence-eval": print(eval(c["pe"]))
                else: exec(c["code"], {})
            c["ans"] = int(buf.getvalue().strip())
